contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(ownedBy != address(0));
        // The test contract is not registered as a program operator, and C exposes
        // no public way to become one, so create() must revert for any input.
        require(!c.programOperators(address(this)));
        bool reverted;
        c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.roundImplementation() == address(0));
    }
    receive() external payable {}
}

